export interface LemlistConfig {
  /** Stable checkpoint namespace for one account; use a new value when switching accounts. */
  sourceId: string
  database: string
  pageSize: number
  start: Date
  overlapMs: number
  intervalMs: number
  /** Empty or omitted discovers all team members for the conversations stream. */
  inboxUserIds?: readonly string[]
}

export type LemlistReaderConfig = Omit<LemlistConfig, 'database'>

// Storage is configured here before schema discovery. Credentials are read at request time.
export const lemlistConfig: LemlistConfig = {
  sourceId: 'lemlist',
  database: 'default',
  pageSize: 100,
  start: new Date('2000-01-01T00:00:00Z'),
  overlapMs: 24 * 60 * 60 * 1000,
  intervalMs: 30 * 24 * 60 * 60 * 1000,
  inboxUserIds: [],
}

import { HttpError, IngestConfigError, paginate, rawRows, type FetchContext, type TimestampRange } from '@chkit/plugin-ingest'

import { lemlistConfig, type LemlistReaderConfig } from './config.js'

interface LemlistItem { _id: string; [key: string]: unknown }

export interface LemlistClientDeps {
  config: LemlistReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultLemlistClientDeps: LemlistClientDeps = {
  config: lemlistConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.LEMLIST_API_KEY,
}

/** Offsets are local traversal positions, never durable change cursors. */
export function readPages(
  context: FetchContext,
  resource: 'activities' | 'campaigns' | 'contacts' | 'companies',
  window: TimestampRange | undefined,
  deps: LemlistClientDeps,
) {
  const seen = new Set<string>()
  return paginate({
    context, initial: 0, label: `GET /${resource}`,
    fetchPage: async (offset = 0, signal) => {
      const params: Record<string, string> = { limit: String(deps.config.pageSize), offset: String(offset) }
      if (resource === 'activities' || resource === 'campaigns') params.version = 'v2'
      if (window) {
        params.minDate = window.from.toISOString()
        params.maxDate = window.to.toISOString()
      } else if (resource !== 'contacts') {
        params.sortBy = 'createdAt'
        params.sortOrder = 'asc'
      }
      const result = await requestLemlist(`/${resource}`, params, signal, deps)
      let items: LemlistItem[]
      let next: number | undefined
      if (resource === 'contacts' || resource === 'companies') {
        const response = requireObject(result, `${resource} listing`)
        items = requireItems(response.data, resource)
        const limit = requireInteger(response.limit, 'listing limit', 1)
        const total = requireInteger(response.total, 'listing total')
        if (response.offset !== offset || limit > deps.config.pageSize || items.length > limit ||
          offset + items.length > total || (items.length < limit && offset + items.length < total)) {
          throw new IngestConfigError(`Lemlist ${resource} has inconsistent pagination; replay this stream.`)
        }
        next = offset + items.length < total ? offset + limit : undefined
      } else {
        // The public API returns arrays; retain compatibility with older campaign envelopes.
        items = requireItems(resource === 'campaigns' && isObject(result) ? result.campaigns : result, resource)
        if (items.length > deps.config.pageSize) throw new IngestConfigError(`Lemlist ${resource} exceeds pageSize.`)
        next = items.length === deps.config.pageSize ? offset + items.length : undefined
      }
      rejectRepeatedPage(items, seen, resource)
      if (next !== undefined && !Number.isSafeInteger(next)) throw new IngestConfigError('Lemlist offset exceeded the safe integer range.')
      return { items, next }
    },
  })
}

/** Inbox pagination is page-based; the messages endpoint accepts the equivalent skip. */
export function readInboxPages(context: FetchContext, scope: { userId: string } | { contactId: string }, deps: LemlistClientDeps) {
  const path = 'userId' in scope ? '/inbox' : `/inbox/${encodeURIComponent(scope.contactId)}`
  const seen = new Set<string>()
  let expectedTotal: number | undefined
  let received = 0
  return paginate({
    context, initial: { page: 1, skip: 0 }, label: `GET ${path}`,
    fetchPage: async (cursor = { page: 1, skip: 0 }, signal) => {
      const params: Record<string, string> = { limit: String(deps.config.pageSize) }
      if ('userId' in scope) {
        params.userId = scope.userId
        params.page = String(cursor.page)
      } else {
        params.skip = String(cursor.skip)
        params.markAsRead = 'false'
      }
      const response = requireObject(await requestLemlist(path, params, signal, deps), 'inbox listing')
      const items = requireItems(response.data, path)
      const pagination = requireObject(response.pagination, 'inbox pagination')
      const total = requireInteger(pagination.totalItems, 'inbox totalItems')
      const perPage = requireInteger(pagination.perPage, 'inbox perPage', 1)
      const currentPage = requireInteger(pagination.currentPage, 'inbox currentPage', 1)
      const totalPages = requireInteger(pagination.totalPages, 'inbox totalPages')
      const nextPage = pagination.nextPage
      if (currentPage !== cursor.page || perPage > deps.config.pageSize || items.length > perPage ||
        (expectedTotal !== undefined && total !== expectedTotal) ||
        (nextPage !== null && (!Number.isSafeInteger(nextPage) || nextPage !== currentPage + 1)) ||
        (nextPage !== null && (items.length === 0 || currentPage >= totalPages)) ||
        (nextPage === null && totalPages > currentPage)) {
        throw new IngestConfigError('Lemlist inbox has malformed or incomplete pagination; replay this stream.')
      }
      rejectRepeatedPage(items, seen, path)
      const count = received + items.length
      if (count > total || (nextPage === null && count !== total)) throw new IngestConfigError('Lemlist inbox ended before its advertised complete collection.')
      expectedTotal = total
      received = count
      const next = typeof nextPage === 'number' ? { page: nextPage, skip: cursor.skip + perPage } : undefined
      return { items, next }
    },
  })
}

export async function requestLemlist(path: string, params: Record<string, string>, signal: AbortSignal, deps: LemlistClientDeps): Promise<unknown> {
  const key = deps.token()?.trim()
  if (!key) throw new IngestConfigError('Set LEMLIST_API_KEY.')
  const url = new URL(`https://api.lemlist.com/api${path}`)
  for (const [name, value] of Object.entries(params)) url.searchParams.set(name, value)
  const response = await deps.fetch(url.toString(), {
    signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error',
    headers: { Authorization: `Basic ${Buffer.from(`:${key}`).toString('base64')}` },
  })
  if (!response.ok) throw await HttpError.fromResponse(response)
  try {
    return await response.json()
  } catch (cause) {
    if (cause instanceof SyntaxError) throw new IngestConfigError(`Lemlist ${path} returned invalid JSON.`)
    throw cause
  }
}

export function toLemlistRows(items: readonly LemlistItem[], deps: LemlistClientDeps, parent?: { campaign_id: string } | { contact_id: string } | { user_id: string }) {
  return rawRows(items.map((data) => ({ source_id: deps.config.sourceId, ...parent, data })), ({ data }) =>
    JSON.stringify([deps.config.sourceId, ...Object.values(parent ?? {}), data._id]))
}

export function requireItems(value: unknown, label: string): LemlistItem[] {
  if (!Array.isArray(value) || !value.every(isItem)) throw new IngestConfigError(`Lemlist ${label} response has no valid items.`)
  const ids = value.map((item) => item._id)
  if (new Set(ids).size !== ids.length) throw new IngestConfigError(`Lemlist ${label} repeated an object ID.`)
  return value
}

export function requireObject(value: unknown, label: string): Record<string, unknown> {
  if (!isObject(value)) throw new IngestConfigError(`Lemlist ${label} is not an object.`)
  return value
}

export function requireId(value: unknown, label: string): string {
  if (typeof value !== 'string' || !value.trim()) throw new IngestConfigError(`Lemlist ${label} has no valid ID.`)
  return value
}

function rejectRepeatedPage(items: readonly LemlistItem[], seen: Set<string>, label: string) {
  if (items.some((item) => seen.has(item._id))) throw new IngestConfigError(`Lemlist ${label} repeated a page or object ID; replay this stream.`)
  for (const item of items) seen.add(item._id)
}

function requireInteger(value: unknown, label: string, minimum = 0): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < minimum) throw new IngestConfigError(`Lemlist ${label} is invalid.`)
  return value
}

function isItem(value: unknown): value is LemlistItem {
  return isObject(value) && typeof value._id === 'string' && value._id.trim().length > 0
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

import { definePipeline, defineStream, fullSync, IngestConfigError } from '@chkit/plugin-ingest'

import { defaultLemlistClientDeps, type LemlistClientDeps } from './client.js'
import { lemlistConfig, type LemlistReaderConfig } from './config.js'
import { createActivityWindow, lemlist_activitiesRaw, readActivities } from './sources/activities.js'
import { lemlist_campaignsRaw, readCampaigns } from './sources/campaigns.js'
import { lemlist_contactsRaw, readContacts } from './sources/contacts.js'
import { lemlist_companiesRaw, readCompanies } from './sources/companies.js'
import { lemlist_campaignLeadsRaw, readCampaignLeads } from './sources/campaign-leads.js'
import { lemlist_inboxConversationsRaw, readInboxConversations } from './sources/inbox-conversations.js'
import { lemlist_inboxMessagesRaw, readInboxMessages } from './sources/inbox-messages.js'

/** One account pipeline; every resource owns its discovery and checkpoint. */
export function createLemlistPipeline(config: LemlistReaderConfig = lemlistConfig, deps: LemlistClientDeps = defaultLemlistClientDeps) {
  if (!config.sourceId.trim() || !Number.isSafeInteger(config.pageSize) || config.pageSize <= 0 || config.pageSize > 100 ||
    !Number.isSafeInteger(config.intervalMs) || config.intervalMs <= 0 ||
    (config.inboxUserIds !== undefined && (!Array.isArray(config.inboxUserIds) ||
      config.inboxUserIds.some((id) => typeof id !== 'string' || !id.trim()) || new Set(config.inboxUserIds).size !== config.inboxUserIds.length))) {
    throw new IngestConfigError('Lemlist needs a sourceId, pageSize from 1 to 100, positive intervalMs, and distinct nonempty inboxUserIds.')
  }
  const client = { ...deps, config: { ...config, start: new Date(config.start), inboxUserIds: config.inboxUserIds ? [...config.inboxUserIds] : undefined } }
  return definePipeline({
    id: config.sourceId, tags: ['provider:lemlist'], maxStreams: 1, maxFetches: 1,
    streams: [
      defineStream({
        id: `${config.sourceId}.activities`, tags: ['resource:activities'], destination: lemlist_activitiesRaw,
        incremental: createActivityWindow(client.config), batchSize: 500,
        read: (context) => readActivities(context, client),
      }),
      defineStream({
        id: `${config.sourceId}.campaigns`, tags: ['resource:campaigns'], destination: lemlist_campaignsRaw,
        incremental: fullSync(),
        read: (context) => readCampaigns(context, client),
      }),
      defineStream({ id: `${config.sourceId}.contacts`, tags: ['resource:contacts'], destination: lemlist_contactsRaw,
        incremental: fullSync(), read: (context) => readContacts(context, client) }),
      defineStream({ id: `${config.sourceId}.companies`, tags: ['resource:companies'], destination: lemlist_companiesRaw,
        incremental: fullSync(), read: (context) => readCompanies(context, client) }),
      defineStream({ id: `${config.sourceId}.campaign_leads`, tags: ['resource:campaign_leads'], destination: lemlist_campaignLeadsRaw,
        incremental: fullSync(), read: (context) => readCampaignLeads(context, client) }),
      defineStream({ id: `${config.sourceId}.inbox_conversations`, tags: ['resource:inbox_conversations'], destination: lemlist_inboxConversationsRaw,
        incremental: fullSync(), read: (context) => readInboxConversations(context, client) }),
      defineStream({ id: `${config.sourceId}.inbox_messages`, tags: ['resource:inbox_messages'], destination: lemlist_inboxMessagesRaw,
        incremental: fullSync(), read: (context) => readInboxMessages(context, client) }),
    ],
  })
}

export const lemlistPipeline = createLemlistPipeline()

import { IngestConfigError, rawRows, rawTable, timestampWindow, type IncrementalStrategy, type ReadContext, type TimestampRange, type TimestampWindowState } from '@chkit/plugin-ingest'

import { readPages, type LemlistClientDeps } from '../client.js'
import { lemlistConfig, type LemlistReaderConfig } from '../config.js'

export const lemlist_activitiesRaw = rawTable({ database: lemlistConfig.database, name: 'lemlist_activities_raw' })

export async function* readActivities(context: ReadContext<TimestampRange, TimestampWindowState>, deps: LemlistClientDeps) {
  for (let from = context.selection.from; from < context.selection.to;) {
    const to = new Date(Math.min(from.getTime() + deps.config.intervalMs, context.selection.to.getTime()))
    for await (const page of readPages(context, 'activities', { from, to }, deps)) {
      yield { rows: rawRows(page.items, (item) => item._id) }
    }
    // Only an exhausted interval is a safe frontier. Its mutable offsets restart at zero.
    const watermark = new Date(Math.max(to.getTime(), Date.parse(context.state?.watermark ?? to.toISOString()))).toISOString()
    yield { rows: [], state: { watermark }, id: `completed-interval:${from.toISOString()}/${to.toISOString()}` }
    from = to
  }
}

export function createActivityWindow(config: LemlistReaderConfig): IncrementalStrategy<TimestampWindowState, TimestampRange> {
  const window = timestampWindow({ start: config.start, overlapMs: config.overlapMs })
  return {
    ...window,
    plan(input: Parameters<typeof window.plan>[0]) {
      const selection = window.plan(input)
      if (input.range && input.state) {
        const frontier = Date.parse(input.state.watermark)
        if (selection.to.getTime() < frontier) {
          throw new IngestConfigError('Lemlist backfill upper bound precedes its committed interval frontier; use a new backfill ID for a narrower historical range.')
        }
        return { ...selection, from: new Date(Math.max(selection.from.getTime(), frontier - config.overlapMs)) }
      }
      return selection
    },
  }
}

import { rawRows, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { readPages, type LemlistClientDeps } from '../client.js'
import { lemlistConfig } from '../config.js'

export const lemlist_campaignsRaw = rawTable({ database: lemlistConfig.database, name: 'lemlist_campaigns_raw' })

// No reliable modification filter: default fullSync records completion and safely replays failures.
export async function* readCampaigns(context: FetchContext, deps: LemlistClientDeps) {
  for await (const page of readPages(context, 'campaigns', undefined, deps)) {
    yield { rows: rawRows(page.items, (item) => item._id) }
  }
}

import { afterEach, expect, test } from 'bun:test'
import { IngestConfigError, runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { createLemlistPipeline, lemlistPipeline } from '../index.js'
import { lemlistConfig } from '../config.js'
import { defaultLemlistClientDeps } from '../client.js'

const originalFetch = globalThis.fetch
const originalToken = process.env.LEMLIST_API_KEY
const cutoff = new Date('2000-03-01T00:00:00Z')

function setFetch(handler: (...args: Parameters<typeof fetch>) => Promise<Response>): void {
  globalThis.fetch = Object.assign(handler, { preconnect: originalFetch.preconnect })
  process.env.LEMLIST_API_KEY = 'fixture'
}

function selected(resource = 'activities') {
  return selectStreams([lemlistPipeline], [`resource:${resource}`]).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
}

afterEach(() => {
  globalThis.fetch = originalFetch
  if (originalToken === undefined) delete process.env.LEMLIST_API_KEY
  else process.env.LEMLIST_API_KEY = originalToken
})

test.serial('Lemlist commits only exhausted date intervals and replays the unfinished interval with overlap', async () => {
  let fail = true
  const journal = createMemoryJournal()
  let acknowledgeInterval = () => {}
  const intervalCommitted = new Promise<void>((resolve) => { acknowledgeInterval = resolve })
  const append = journal.append
  journal.append = async (events) => {
    await append(events)
    if (events.some((event) => JSON.stringify(event.checkpoint?.state) === '{"watermark":"2000-01-31T00:00:00.000Z"}')) acknowledgeInterval()
  }
  const windows: { from: string | null; to: string | null; offset: string | null }[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    const from = url.searchParams.get('minDate')
    windows.push({ from, to: url.searchParams.get('maxDate'), offset: url.searchParams.get('offset') })
    if (fail && from !== '2000-01-01T00:00:00.000Z') {
      await intervalCommitted
      return new Response('denied', { status: 403 })
    }
    return Response.json([{ _id: from, custom: { retained: true } }])
  })
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: '2000-01-31T00:00:00.000Z' })
  expect(destination.tables.get('default.lemlist_activities_raw')?.[0]?.raw).toMatchObject({ custom: { retained: true } })
  fail = false
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(windows[2]).toEqual({ from: '2000-01-30T00:00:00.000Z', to: '2000-02-29T00:00:00.000Z', offset: '0' })
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test.serial('Lemlist resumes isolated explicit backfills from the completed interval frontier', async () => {
  let fail = true
  const starts: string[] = []
  setFetch(async (input) => {
    const from = new URL(String(input)).searchParams.get('minDate') ?? ''
    starts.push(from)
    if (fail && from !== '2025-01-01T00:00:00.000Z') return new Response('denied', { status: 403 })
    return Response.json([])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: { id: 'history', from: new Date('2025-01-01T00:00:00Z'), to: new Date('2025-03-01T00:00:00Z') } }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities#backfill:history')).envelope?.state).toEqual({ watermark: '2025-01-31T00:00:00.000Z' })
  fail = false
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(true)
  expect(starts[2]).toBe('2025-01-30T00:00:00.000Z')
  expect((await journal.readCheckpoint('lemlist.activities')).envelope).toBeUndefined()
})

test.serial('Lemlist rejects a narrowed completed backfill upper bound without regressing its frontier', async () => {
  let requests = 0
  setFetch(async () => { requests++; return Response.json([]) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const backfill = { id: 'narrowed', from: new Date('2025-01-01T00:00:00Z'), to: new Date('2025-03-01T00:00:00Z') }
  const request = { selected: selected(), backfill }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(true)
  const completedRequests = requests
  // This upper bound is still after the overlap's lower bound, but must not move the watermark backwards.
  const result = await runIngestion({ ...request, backfill: { ...backfill, to: new Date('2025-02-28T12:00:00Z') } }, {
    journal, destination, now: () => new Date('2026-01-01'),
  })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('use a new backfill ID')
  expect(requests).toBe(completedRequests)
  expect((await journal.readCheckpoint('lemlist.activities#backfill:narrowed')).envelope?.state).toEqual({ watermark: '2025-03-01T00:00:00.000Z' })
})

test.serial('Lemlist paginates a whole date interval and a rejected sink cannot advance it', async () => {
  const offsets: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    offsets.push(url.searchParams.get('offset') ?? '')
    expect(url.searchParams.get('minDate')).toBe('2000-01-01T00:00:00.000Z')
    expect(url.searchParams.get('maxDate')).toBe('2000-01-02T00:00:00.000Z')
    return Response.json(url.searchParams.get('offset') === '0' ? Array.from({ length: 100 }, (_, index) => ({ _id: String(index) })) : [{ _id: 'last' }])
  })
  const journal = createMemoryJournal()
  const request = { selected: selected(), backfill: undefined }
  const result = await runIngestion(request, { journal, destination: { insert: async () => { throw new IngestConfigError('sink rejected') } }, now: () => new Date('2000-01-02') })
  expect(result.ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope).toBeUndefined()
  expect(offsets).toEqual(['0', '100'])
})

test.serial('Lemlist empty activity intervals commit and campaigns always scan from zero', async () => {
  const paths: URL[] = []
  setFetch(async (input) => { paths.push(new URL(String(input))); return Response.json({ campaigns: [] }) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected('campaigns'), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2000-03-02') })).ok).toBe(true)
  expect(paths.map((url) => url.searchParams.get('offset'))).toEqual(['0', '0'])
  expect(paths.every((url) => url.searchParams.get('sortBy') === 'createdAt' && url.searchParams.get('sortOrder') === 'asc')).toBe(true)
  expect((await journal.readCheckpoint('lemlist.campaigns')).lastSuccessSeq).toBeGreaterThan(0)
  expect(journal.events.filter((event) => event.namespaceId === 'lemlist.campaigns' && event.eventKind === 'work_finished' && event.workState === 'succeeded')).toHaveLength(2)
  setFetch(async () => Response.json([]))
  expect((await runIngestion({ selected: selected(), backfill: undefined }, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test('Lemlist binds account configuration to independent resource streams and preserves activity progress after a campaign failure', async () => {
  const config = { ...lemlistConfig, sourceId: 'lemlist.sales', pageSize: 2, start: new Date('2026-01-01'), overlapMs: 0, intervalMs: 24 * 60 * 60 * 1000 }
  const urls: URL[] = []
  let campaignsAvailable = false
  const pipeline = createLemlistPipeline(config, {
    ...defaultLemlistClientDeps, token: () => 'sales-key',
    fetch: async (input, init) => {
      const url = new URL(input)
      urls.push(url)
      expect(init.headers).toEqual({ Authorization: `Basic ${Buffer.from(':sales-key').toString('base64')}` })
      if (url.pathname.endsWith('/campaigns')) return campaignsAvailable ? Response.json({ campaigns: [] }) : new Response('denied', { status: 403 })
      return Response.json(url.searchParams.get('offset') === '0' ? [{ _id: 'a' }, { _id: 'b' }] : [{ _id: 'c', custom: true }])
    },
  })
  config.pageSize = 100
  config.start.setUTCFullYear(2000)
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const selected = selectStreams([pipeline], []).filter((item) => ['lemlist.sales.activities', 'lemlist.sales.campaigns'].includes(item.stream.id))
    .map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
  const result = await runIngestion({ selected, backfill: undefined }, { journal, destination, now: () => new Date('2026-01-02') })
  expect(result.streams.map((stream) => [stream.streamId, stream.outcome])).toEqual([
    ['lemlist.sales.activities', 'succeeded'], ['lemlist.sales.campaigns', 'failed'],
  ])
  expect((await journal.readCheckpoint('lemlist.sales.activities')).envelope?.state).toEqual({ watermark: '2026-01-02T00:00:00.000Z' })
  expect((await journal.readCheckpoint('lemlist.sales.campaigns')).lastSuccessSeq).toBe(0)
  expect(urls.filter((url) => url.pathname.endsWith('/activities')).map((url) => [url.searchParams.get('minDate'), url.searchParams.get('offset'), url.searchParams.get('limit')])).toEqual([
    ['2026-01-01T00:00:00.000Z', '0', '2'], ['2026-01-01T00:00:00.000Z', '2', '2'],
  ])
  expect(destination.tables.get('default.lemlist_activities_raw')?.map((row) => row.id)).toEqual(['a', 'b', 'c'])
  campaignsAvailable = true
  urls.length = 0
  expect((await runIngestion({ selected: selectStreams([pipeline], ['resource:campaigns']), backfill: undefined }, { journal, destination })).ok).toBe(true)
  expect(urls.map((url) => url.pathname)).toEqual(['/api/campaigns'])
  expect((await journal.readCheckpoint('lemlist.sales.campaigns')).lastSuccessSeq).toBeGreaterThan(0)
